describe('File Upload - Upload Button Disabled During Upload', () => {
  beforeEach(() => {
    cy.visit('/upload');
    cy.get('[data-testid="upload-button"]').should('be.enabled');
  });

  it('should disable upload button while file is uploading', () => {
    const fileName = 'test-file.pdf';

    cy.intercept('POST', '/api/upload', (req) => {
      req.reply((res) => {
        res.delay(2000);
        res.send({
          statusCode: 200,
          body: { success: true, fileId: '12345' }
        });
      });
    }).as('uploadRequest');

    cy.get('input[type="file"]').selectFile(`cypress/fixtures/${fileName}`);

    cy.get('[data-testid="upload-button"]').click();

    cy.get('[data-testid="upload-button"]').should('be.disabled');
    cy.get('[data-testid="upload-button"]').should('have.attr', 'disabled');

    cy.wait('@uploadRequest');

    cy.get('[data-testid="upload-button"]').should('be.enabled');
  });

  it('should keep upload button disabled during multiple file uploads', () => {
    const fileName1 = 'test-file-1.pdf';
    const fileName2 = 'test-file-2.pdf';

    cy.intercept('POST', '/api/upload', (req) => {
      req.reply((res) => {
        res.delay(3000);
        res.send({
          statusCode: 200,
          body: { success: true, fileId: Math.random() }
        });
      });
    }).as('uploadRequest');

    cy.get('input[type="file"]').selectFile(`cypress/fixtures/${fileName1}`);
    cy.get('[data-testid="upload-button"]').click();

    cy.get('[data-testid="upload-button"]').should('be.disabled');

    cy.wait('@uploadRequest');
    cy.get('[data-testid="upload-button"]').should('be.enabled');

    cy.get('input[type="file"]').selectFile(`cypress/fixtures/${fileName2}`);
    cy.get('[data-testid="upload-button"]').click();

    cy.get('[data-testid="upload-button"]').should('be.disabled');
    cy.get('[data-testid="upload-button"]').should('have.class', 'disabled');

    cy.wait('@uploadRequest');
    cy.get('[data-testid="upload-button"]').should('be.enabled');
  });

  it('should handle upload failure and re-enable button', () => {
    const fileName = 'test-file.pdf';

    cy.intercept('POST', '/api/upload', (req) => {
      req.reply((res) => {
        res.delay(1500);
        res.send({
          statusCode: 500,
          body: { success: false, error: 'Upload failed' }
        });
      });
    }).as('uploadRequest');

    cy.get('input[type="file"]').selectFile(`cypress/fixtures/${fileName}`);
    cy.get('[data-testid="upload-button"]').click();

    cy.get('[data-testid="upload-button"]').should('be.disabled');

    cy.wait('@uploadRequest');

    cy.get('[data-testid="upload-button"]').should('be.enabled');
    cy.get('[data-testid="error-message"]').should('contain', 'Upload failed');
  });

  it('should disable button immediately on click and show loading state', () => {
    const fileName = 'test-file.pdf';

    cy.intercept('POST', '/api/upload', (req) => {
      req.reply((res) => {
        res.delay(2500);
        res.send({
          statusCode: 200,
          body: { success: true, fileId: '12345' }
        });
      });
    }).as('uploadRequest');

    cy.get('input[type="file"]').selectFile(`cypress/fixtures/${fileName}`);

    cy.get('[data-testid="upload-button"]').click();

    cy.get('[data-testid="upload-button"]').should('be.disabled');
    cy.get('[data-testid="upload-button"]').should('have.attr', 'aria-busy', 'true');
    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    cy.wait('@uploadRequest');

    cy.get('[data-testid="upload-button"]').should('be.enabled');
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
  });
});
